CREATE VIEW v_patient_lab AS SELECT Patient.ID AS patient_id, Patient.SEX AS sex, Patient.Birthday AS birthday, Patient.Admission AS admission, Patient.Diagnosis AS patient_diagnosis, Laboratory.Date AS lab_date, Laboratory.GOT, Laboratory.GPT, Laboratory.LDH, Laboratory.ALP, Laboratory.TP, Laboratory.ALB, Laboratory.UA, Laboratory.UN, Laboratory.CRE, Laboratory."T-BIL" AS t_bil, Laboratory."T-CHO" AS t_cho, Laboratory.TG, Laboratory.CPK, Laboratory.GLU, Laboratory.WBC, Laboratory.RBC, Laboratory.HGB, Laboratory.HCT, Laboratory.PLT, Laboratory.PT, Laboratory.APTT, Laboratory.FG, Laboratory.CRP, Laboratory.IGG, Laboratory.IGA, Laboratory.IGM, Patient.Description, Patient."First Date", Laboratory.ID, Laboratory.PIC, Laboratory.TAT, Laboratory.TAT2, Laboratory."U-PRO", Laboratory.RA, Laboratory.RF, Laboratory.C3, Laboratory.C4, Laboratory.RNP, Laboratory.SM, Laboratory.SC170, Laboratory.SSA, Laboratory.SSB, Laboratory.CENTROMEA, Laboratory.DNA, Laboratory."DNA-II" FROM Patient LEFT JOIN Laboratory ON Patient.ID = Laboratory.ID;

CREATE VIEW v_patient_exam AS SELECT Patient.ID AS patient_id, Patient.SEX AS sex, Patient.Birthday AS birthday, Patient.Admission AS admission, Examination."Examination Date" AS exam_date, Examination."aCL IgG" AS acl_igg, Examination."aCL IgM" AS acl_igm, Examination.ANA, Examination."ANA Pattern" AS ana_pattern, Examination.Diagnosis AS exam_diagnosis, Examination.Symptoms AS symptoms, Examination.Thrombosis AS thrombosis, Patient.Description, Patient."First Date", Patient.Diagnosis, Examination.ID, Examination."aCL IgA", Examination.KCT, Examination.RVVT, Examination.LAC FROM Patient LEFT JOIN Examination ON Patient.ID = Examination.ID;
